<style>
    .dxm-alert{border:1px solid rgba(34,197,94,.35);background:rgba(34,197,94,.12);color:#bbf7d0;padding:12px 14px;border-radius:14px;margin-bottom:14px;font-weight:750;font-size:13px}.builder-tabs{display:flex;gap:8px;overflow-x:auto;padding:10px;border:1px solid rgba(255,255,255,.08);background:rgba(2,6,23,.25);border-radius:20px;margin-bottom:16px;scrollbar-width:thin}.builder-tab{border:1px solid rgba(255,255,255,.10);background:rgba(2,6,23,.55);color:rgba(255,255,255,.78);border-radius:999px;padding:11px 15px;font-size:12px;font-weight:850;white-space:nowrap;cursor:pointer}.builder-tab.is-active{background:linear-gradient(135deg,rgba(34,211,238,.28),rgba(29,92,255,.28));border-color:rgba(34,211,238,.55);color:#fff;box-shadow:0 0 0 1px rgba(34,211,238,.12) inset}.builder-panel{display:none}.builder-panel.is-active{display:block}.unified-form-grid,.panel-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:16px!important;width:100%!important}.field,.check,.panel{min-width:0!important}.full{grid-column:1/-1!important}.field label,.panel h3{display:block;margin:0 0 7px;color:rgba(255,255,255,.80);font-size:12px;font-weight:750;line-height:1.25}.panel h3{font-size:14px;font-weight:850;color:rgba(255,255,255,.90);margin-bottom:14px}.field input,.field select,.field textarea{width:100%!important;max-width:100%!important;box-sizing:border-box!important;border-radius:14px;border:1px solid rgba(255,255,255,.10);background:rgba(2,6,23,.74);color:#fff;padding:12px 13px;outline:none;min-height:46px;font-size:13px;font-weight:560}.field input[type=file]{padding:10px;cursor:pointer;font-size:12px}.field small{display:block;margin-top:7px;color:rgba(255,255,255,.55);line-height:1.35;font-size:11.5px;font-weight:520}.panel,.builder-note{border:1px solid rgba(255,255,255,.08);background:rgba(2,6,23,.26);border-radius:18px;padding:16px}.builder-note{display:grid;gap:7px;color:rgba(255,255,255,.68);font-size:13px;line-height:1.45}.builder-note strong{color:#fff}.builder-note code{color:#93c5fd;background:rgba(59,130,246,.12);padding:2px 5px;border-radius:6px}.watch-source-panel{border-color:rgba(34,211,238,.22);background:linear-gradient(135deg,rgba(34,211,238,.08),rgba(168,85,247,.06))}.watch-source-help{margin:-4px 0 14px;color:rgba(255,255,255,.60);font-size:12px;line-height:1.45}.watch-source-preview{display:grid;gap:4px;border:1px solid rgba(34,211,238,.16);background:rgba(34,211,238,.07);border-radius:16px;padding:12px}.watch-source-preview strong{color:#fff;font-size:13px}.watch-source-preview span{color:rgba(255,255,255,.58);font-size:12px;line-height:1.4}.check{display:flex;align-items:center;gap:10px;color:rgba(255,255,255,.78);font-weight:700;font-size:12.5px;line-height:1.35}.enabled{min-height:46px;align-self:end}.action-row{display:flex;justify-content:flex-end;gap:12px;flex-wrap:wrap;margin-top:18px}.danger-box{margin-top:14px;padding:14px;border-radius:18px;border:1px solid rgba(248,113,113,.35);background:rgba(127,29,29,.16);display:flex;justify-content:flex-end}.dxm-btn--danger{background:linear-gradient(135deg,#ef4444,#be123c)!important;color:#fff!important}.app-card{position:relative;width:100%;min-height:255px;border-radius:24px;overflow:hidden;background:linear-gradient(135deg,#0B1F4D,#1D5CFF,#E2388A);border:1px solid rgba(255,255,255,.10)}.preview-bg{position:absolute;inset:0;background:linear-gradient(135deg,#0B1F4D,#1D5CFF,#E2388A)}.preview-bg img{width:100%;height:100%;object-fit:cover;object-position:center center;display:block}.preview-bg.is-empty::before,.preview-bg.is-empty::after{content:"";position:absolute;border-radius:999px;background:rgba(255,255,255,.12)}.preview-bg.is-empty::before{right:-50px;top:-50px;width:160px;height:160px}.preview-bg.is-empty::after{left:-40px;bottom:-50px;width:150px;height:150px;background:rgba(255,255,255,.08)}.preview-shade{position:absolute;inset:0;background:linear-gradient(to bottom,rgba(0,0,0,.02) 0%,rgba(0,0,0,.12) 42%,rgba(0,0,0,.82) 100%)}.preview-badge{position:absolute;top:16px;left:16px;z-index:4;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.22);color:#fff;border-radius:999px;padding:7px 10px;font-size:10.5px;text-transform:uppercase;letter-spacing:.06em;font-weight:900}.preview-badge.is-empty{display:none}.preview-icon{position:absolute;top:16px;right:16px;width:42px;height:42px;border-radius:999px;display:grid;place-items:center;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.18);color:#fff;z-index:3}.preview-icon svg{width:23px;height:23px;display:block}.preview-icon.is-empty{display:none}.preview-content{position:absolute;left:18px;right:18px;bottom:18px;z-index:4}.preview-kicker{display:inline-flex;margin-bottom:9px;color:#bfdbfe;font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;font-weight:950}.preview-title{color:#fff;font-size:20px;line-height:1.12;font-weight:850;text-shadow:0 2px 8px rgba(0,0,0,.35)}.preview-subtitle{color:rgba(255,255,255,.88);font-size:12.5px;line-height:1.35;font-weight:580;margin-top:7px}.preview-details{margin-top:16px;border:1px solid rgba(255,255,255,.08);background:rgba(2,6,23,.25);border-radius:18px;padding:14px;display:grid;gap:8px;color:rgba(255,255,255,.68);font-size:12.5px;word-break:break-word;line-height:1.35}.preview-details strong{color:rgba(255,255,255,.82);font-weight:750}.content-workflow-box{display:flex;justify-content:space-between;gap:14px;align-items:center;border:1px solid rgba(56,189,248,.25);background:linear-gradient(135deg,rgba(14,165,233,.14),rgba(226,56,138,.10));border-radius:20px;padding:16px;margin-bottom:16px}.workflow-copy span{display:block;color:rgba(255,255,255,.55);font-size:11px;text-transform:uppercase;letter-spacing:.06em;font-weight:900}.workflow-copy strong{display:block;color:#fff;font-size:18px;margin-top:4px}.workflow-copy small{display:block;color:rgba(255,255,255,.62);font-size:12px;margin-top:5px;line-height:1.35}.workflow-actions{display:flex;gap:10px;flex-wrap:wrap}@media(max-width:760px){.unified-form-grid,.panel-grid{grid-template-columns:1fr!important}.content-workflow-box{display:block}.workflow-actions{margin-top:13px}.workflow-actions .dxm-btn,.action-row .dxm-btn,.danger-box .dxm-btn{width:100%;text-align:center}.action-row,.danger-box{justify-content:stretch}.builder-tabs{padding:8px}.builder-tab{padding:10px 12px}}
</style>

<script>
(function(){
    const iconSvgs=@json($iconSvgMap ?? []);
    const labels={
        item_kind:{card:'General Card',banner:'Image Banner',button:'Button',text:'Text Notice',quote:'Quote Card',short_video:'Short Video',article:'Article Item',book:'Book Item',quiz:'Quiz Item',watch:'Watch Item',external:'External Link',ad_slot:'Ad Slot',custom:'Custom Item'},
        source_type:{manual:'Manual',content_channel:'Content Channel',quote_channel:'Quote Channel',short_video_channel:'Short Video Channel',book_channel:'Books',quiz_channel:'Quiz',watch_builder:'Watch Builder',external_link:'External Link',ad_slot:'Ad Slot',mixed:'Mixed Content'},
        action_type:{route:'Inner App Page',webview:'Web Page',external_url:'External Link',youtube_video:'YouTube Video',youtube_playlist:'YouTube Playlist',live_stream:'Live Stream'}
    };
    function byId(id){return document.getElementById(id)}
    function value(id){const el=byId(id);return el ? (el.value||'').trim() : ''}
    function checked(id){const el=byId(id);return !!(el&&el.checked)}
    function esc(v){return String(v||'').replace(/[&<>"']/g,function(m){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'})[m];});}
    document.querySelectorAll('.builder-tab').forEach(function(tab){tab.addEventListener('click',function(){const target=tab.getAttribute('data-tab');document.querySelectorAll('.builder-tab').forEach(t=>t.classList.remove('is-active'));document.querySelectorAll('.builder-panel').forEach(p=>p.classList.remove('is-active'));tab.classList.add('is-active');const panel=document.querySelector('[data-panel="'+target+'"]');if(panel)panel.classList.add('is-active');});});
    function updateWatchSource(){const watchLinkInput=byId('watch_link_id');const watchSourcePreview=byId('watchSourcePreview');const actionInput=byId('action_type');const urlInput=byId('url');const youtubeInput=byId('youtube');if(!watchLinkInput||!watchSourcePreview)return;const option=watchLinkInput.options[watchLinkInput.selectedIndex];const watchUrl=option?option.getAttribute('data-url'):'';const watchTitle=option?option.getAttribute('data-title'):'';const watchType=option?option.getAttribute('data-type'):'';const watchPlayer=option?option.getAttribute('data-player'):'';if(option&&watchLinkInput.value&&watchLinkInput.value!=='0'){watchSourcePreview.innerHTML='<strong>'+esc(watchTitle||'Selected watch source')+'</strong><span>'+esc(watchType||'watch link')+' · '+esc(watchPlayer||'auto player')+'</span><span>'+esc(watchUrl||'No URL set yet')+'</span>';if(watchUrl&&actionInput){const currentAction=actionInput.value;if(currentAction==='route'){if((watchType||'').includes('live')){actionInput.value='live_stream';}else if((watchPlayer||'')==='youtube'||watchUrl.includes('youtube.com')||watchUrl.includes('youtu.be')){actionInput.value='youtube_playlist';}else{actionInput.value='webview';}}if(actionInput.value==='youtube_video'||actionInput.value==='youtube_playlist'){if(youtubeInput&&!youtubeInput.value)youtubeInput.value=watchUrl;}else{if(urlInput&&!urlInput.value)urlInput.value=watchUrl;}}}else{watchSourcePreview.innerHTML='<strong>No watch source selected.</strong><span>Manual URL fields will be used until you choose a source.</span>';}}
    function updatePreview(){
        const imageInput=byId('image_url');const clearImage=checked('clear_image');const imageUrl=clearImage?'':(imageInput?imageInput.value.trim():'');const iconKey=value('icon');const iconSvg=iconSvgs[iconKey]||'';const previewImage=byId('itemPreviewImage');const previewIcon=byId('itemPreviewIcon');const previewBadge=byId('itemPreviewBadge');
        if(previewImage){previewImage.classList.toggle('is-empty',imageUrl==='');previewImage.innerHTML=imageUrl?`<img src="${esc(imageUrl)}" alt="">`:'';}
        if(previewIcon){if(iconSvg){previewIcon.classList.remove('is-empty');previewIcon.innerHTML=iconSvg;}else{previewIcon.classList.add('is-empty');previewIcon.innerHTML='';}}
        if(previewBadge){const badge=value('badge_text');previewBadge.textContent=badge;previewBadge.classList.toggle('is-empty',badge==='');}
        const set=(id,text)=>{const el=byId(id);if(el)el.textContent=text};
        set('itemPreviewKind',labels.item_kind[value('item_kind')]||'General Card');
        set('itemPreviewTitle',value('title')||'Item title preview');
        set('itemPreviewSubtitle',value('subtitle'));
        set('itemPreviewSource',labels.source_type[value('source_type')]||'Manual');
        set('itemPreviewBucket',value('source_bucket')||'—');
        set('itemPreviewChannel',value('source_channel')||'—');
        set('itemPreviewLayout',(value('layout_template')||'card')+' / '+(value('card_style')||'auto')+' / '+(value('size_preset')||'auto'));
        set('itemPreviewAction',labels.action_type[value('action_type')]||'Preview');
        set('itemPreviewRoute',value('route_key')||'—');
        set('itemPreviewEnabled',checked('is_enabled')?'Enabled':'Disabled');
        updateWatchSource();
    }
    document.querySelectorAll('input, select, textarea').forEach(function(field){field.addEventListener('input',updatePreview);field.addEventListener('change',updatePreview);});
    updatePreview();
})();
</script>
